  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC0RB_1LA1RD_1LC0LB B0_1RB1LD_0LC0RB_1LA1RD_1LC0LB B1_1RB1LD_0LC0RB_1LA1RD_1LC0LB 6 10 p j' [] []).
