(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LC0RB_1LA1RD_1LC0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_0LC0RB_1LA1RD_1LC0LB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_0LC0RB_1LA1RD_1LC0LB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_0LC0RB_1LA1RD_1LC0LB : forall t, ~ In t pins_1RB1LD_0LC0RB_1LA1RD_1LC0LB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_0LC0RB_1LA1RD_1LC0LB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC0LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtr_1RB1LD_0LC0RB_1LA1RD_1LC0LB : NonHalt tm_1RB1LD_0LC0RB_1LA1RD_1LC0LB /\ QHBoundTr 32779478 tm_1RB1LD_0LC0RB_1LA1RD_1LC0LB /\ QuasiHaltsTr tm_1RB1LD_0LC0RB_1LA1RD_1LC0LB.
Proof.
  apply (lap_qh_stage tm_1RB1LD_0LC0RB_1LA1RD_1LC0LB pins_1RB1LD_0LC0RB_1LA1RD_1LC0LB Cc 1 11 32779478).
  - exact bootq_1RB1LD_0LC0RB_1LA1RD_1LC0LB.
  - intros p _. apply lap_1RB1LD_0LC0RB_1LA1RD_1LC0LB.
  - intros t Ht p _. apply fire_1RB1LD_0LC0RB_1LA1RD_1LC0LB. exact Ht.
  - exact wit_1RB1LD_0LC0RB_1LA1RD_1LC0LB.
  - vm_cast_no_check (eq_refl true).
Qed.

