Lemma geo_1RB1LD_0LC0RB_1LA1RD_1LC1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_0LC0RB_1LA1RD_1LC1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_010_01.cview_none_Alph_000_010_01 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LD_0LC0RB_1LA1RD_1LC1LD
             = (StB, (rep [S0;S0;S0] (S j) ++ [S0;S1], S0, []))).
  { unfold cden, B1_1RB1LD_0LC0RB_1LA1RD_1LC1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LD_0LC0RB_1LA1RD_1LC1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LD_0LC0RB_1LA1RD_1LC1LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1LD_0LC0RB_1LA1RD_1LC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_0LC0RB_1LA1RD_1LC1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC0RB_1LA1RD_1LC1LD B0_1RB1LD_0LC0RB_1LA1RD_1LC1LD B1_1RB1LD_0LC0RB_1LA1RD_1LC1LD 6 10 p j' [] []).
    + exact run_ovf_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LC0RB_1LA1RD_1LC1LD p j' E).
    + exact (geo_1RB1LD_0LC0RB_1LA1RD_1LC1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_0LC0RB_1LA1RD_1LC1LD : stepn tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD 14 InitES = Some (lift (Cc 2)).
Proof.
  assert (H : match csteps tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD 14 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_0LC0RB_1LA1RD_1LC1LD : existsb (fun tg => cfires tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD c0 14 tg) pins_1RB1LD_0LC0RB_1LA1RD_1LC1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LC0RB_1LA1RD_1LC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_0LC0RB_1LA1RD_1LC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_0LC0RB_1LA1RD_1LC1LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_0LC0RB_1LA1RD_1LC1LD : forall t, ~ In t pins_1RB1LD_0LC0RB_1LA1RD_1LC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_0LC0RB_1LA1RD_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtr_1RB1LD_0LC0RB_1LA1RD_1LC1LD : NonHalt tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD /\ QHBoundTr 32779478 tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD /\ QuasiHaltsTr tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
Proof.
  apply (lap_qh_stage tm_1RB1LD_0LC0RB_1LA1RD_1LC1LD pins_1RB1LD_0LC0RB_1LA1RD_1LC1LD Cc 2 14 32779478).
  - exact bootq_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
  - intros p _. apply lap_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
  - intros t Ht p _. apply fire_1RB1LD_0LC0RB_1LA1RD_1LC1LD. exact Ht.
  - exact wit_1RB1LD_0LC0RB_1LA1RD_1LC1LD.
  - vm_cast_no_check (eq_refl true).
Qed.

